

window.AGN = window.AGN || {};

AGN.SCHEMA = {
  terrain: ['lat','lon','elev_m','slope_deg','aspect_deg','facing','tpi_300','valley_depth','svf','catchment_km2','landform']
};

/* v91.17.283.18 . one terrain sample row -> its named fields */
AGN.terrainRow = function(row){
  if(!row) return null;
  var S = AGN.SCHEMA.terrain, o = {};
  for(var i=0;i<S.length;i++) o[S[i]] = row[i];
  o.hasTerrain = (row[3] != null);
  return o;
};

/* v91.17.283.18 . THE PLACE LAYER OF THIS PAGE. Every place question goes to the server's one place table (server/api/places.mjs:
   GET /api/geo/search, /api/geo/reverse, /api/geo/near, /api/geo/towns, /api/geo/settlement) through these functions, one call each;
   the page holds no place list of its own and never re-ranks or merges what the server answers. locate() is the one my-location of the
   page: the browser fix, its accuracy, and a coarse network fix (1 km or worse) opens the header's list of places around it. */
AGN.places = (function(){
  function get(u){ return fetch(u,{cache:'no-store'}).then(function(r){ return r.ok?r.json():null; }); }
  function search(q,o){ o=o||{}; return get('/api/geo/search?q='+encodeURIComponent(String(q==null?'':q).trim())+'&limit='+(o.limit||8)+(o.suggest?'&suggest=1':'')); }
  function first(q){ return search(q,{limit:8}).then(function(j){ var r=((j&&j.results)||[]).filter(function(x){ return x&&isFinite(x.lat)&&isFinite(x.lon)&&!x.disputed&&x.administered!==false; })[0];
    return r?{ok:true, q:q, id:r.id||null, lat:r.lat, lon:r.lon, name:r.name, label:r.resolvedLabel||r.name, level:r.level||null, rule:r.resolvedAs||null, tehsil:r.tehsil||null, district:r.district||null, province:r.province||null, confirmed:r.confirmed!==false, elevM:r.elevM!=null?r.elevM:null}:null; }); }
  function reverse(lat,lon){ return get('/api/geo/reverse?lat='+(+lat).toFixed(5)+'&lon='+(+lon).toFixed(5)); }
  function near(lat,lon,km,limit){ return get('/api/geo/near?lat='+(+lat).toFixed(5)+'&lon='+(+lon).toFixed(5)+'&km='+(+km).toFixed(1)+'&limit='+(limit||12)); }
  function unitPoint(district){ return get('/api/geo/settlement?district='+encodeURIComponent(district)); }
  var TW=null, TOWNS=[];
  function loadTowns(){ if(!TW) TW=get('/api/geo/towns').then(function(j){ TOWNS=(j&&j.towns)||[]; return TOWNS; },function(){ TW=null; return []; }); return TW; }
  function townsIn(bb){ if(!TW) loadTowns(); return TOWNS.filter(function(t){ return t.lon>=bb[0]&&t.lon<=bb[2]&&t.lat>=bb[1]&&t.lat<=bb[3]; }).slice(0,40); }
  function locate(){ if(!window.AGNConditions||!AGNConditions.getUserLocation) return Promise.reject(new Error('this browser does not offer location'));
    return AGNConditions.getUserLocation().then(function(p){ var acc=(p&&p.accuracyM!=null&&isFinite(p.accuracyM))?p.accuracyM:null, coarse=acc!=null&&acc>=1000;
      var lab='My location'+(acc==null?'':coarse?' (\u00b1'+(acc/1000).toFixed(acc<10000?1:0)+' km)':' (\u00b1'+Math.round(acc)+' m)');
      if(coarse&&window.__agnCoarseFix) window.__agnCoarseFix(p,acc);
      return {lat:+p.lat, lon:+p.lon, accuracyM:acc, coarse:coarse, label:lab}; }); }
  /* a server row in the shape the older list renderers read (admin1 = province, admin2 = district); the row's own fields are kept */
  function hit(x){ return Object.assign({}, x, {latitude:x.lat, longitude:x.lon, elevation:x.elevM!=null?x.elevM:null, admin1:[x.province, x.note].filter(Boolean).join(' \u00b7 ')||null,
    admin2:[x.tehsil&&x.tehsil!==x.district?x.tehsil+' tehsil':null, x.district].filter(Boolean).join(' \u00b7 ')||null, country_code:'PK', __pop:x.population!=null?x.population:null, __fuzzy:!!x.fuzzy, __score:x.score, _agnLevel:x.level, _agnSource:x.source, _agnId:x.id}); }
  setTimeout(loadTowns, 8000);
  return { search:search, first:first, reverse:reverse, near:near, unitPoint:unitPoint, towns:townsIn, loadTowns:loadTowns, locate:locate, hit:hit };
})();

AGN.require = function(label, test){
  try{
    if(!test()){ console.warn('[AGN] data contract broken:', label); return false; }
  }catch(e){ console.warn('[AGN] contract check threw:', label, e && e.message); return false; }
  return true;
};



