AGN.require('terrain sample row width', function(){
  return AGN_TERRAIN_SAMPLES[0].length === AGN.SCHEMA.terrain.length;
});
AGN.require('terrain samples present', function(){
  return AGN_TERRAIN_SAMPLES.length > 1000;
});

AGN.terrain = (function(){
  var GRID = 0.25, index = null;

  function build(){
    index = Object.create(null);
    for(var i=0;i<AGN_TERRAIN_SAMPLES.length;i++){
      var r = AGN_TERRAIN_SAMPLES[i];
      var k = Math.floor(r[0]/GRID) + ':' + Math.floor(r[1]/GRID);
      (index[k] || (index[k] = [])).push(r);
    }
  }

  

  function atPoint(lat, lon, tolDeg){
    if(!isFinite(lat) || !isFinite(lon)) return null;
    if(!index) build();
    var tol = tolDeg || 0.06, best = null, bd = Infinity;
    var gx = Math.floor(lat/GRID), gy = Math.floor(lon/GRID);
    var cosLat = Math.cos(lat*Math.PI/180);
    var ring = Math.max(1, Math.ceil(tol/GRID));
    for(var dx=-ring; dx<=ring; dx++) for(var dy=-ring; dy<=ring; dy++){
      var cell = index[(gx+dx)+':'+(gy+dy)];
      if(!cell) continue;
      for(var i=0;i<cell.length;i++){
        var r = cell[i], a = r[0]-lat, b = (r[1]-lon)*cosLat;
        var d = a*a + b*b;
        if(d < bd){ bd = d; best = r; }
      }
    }
    if(!best || bd > tol*tol) return null;
    var o = AGN.terrainRow(best);
    o.matchKm = Math.round(Math.sqrt(bd) * 111.32 * 10)/10;
    return o;
  }

   
  function forStation(s){
    if(!s) return null;
    if(s.__terr !== undefined) return s.__terr;
    var t = atPoint(Number(s.lat), Number(s.lon));
    try{ s.__terr = t; }catch(_){}
    return t;
  }

  

  function decorate(s){
    var t = forStation(s);
    if(!t) return s;
    if(s.landform == null)      s.landform      = t.landform;
    if(s.tpi_300 == null)       s.tpi_300       = t.tpi_300;
    if(s.slope == null)         s.slope         = t.slope_deg;
    if(s.slope_deg == null)     s.slope_deg     = t.slope_deg;
    if(s.aspect_deg == null)    s.aspect_deg    = t.aspect_deg;
    if(s.facing == null)        s.facing        = t.facing;
    if(s.svf == null)           s.svf           = t.svf;
    if(s.valley_depth == null)  s.valley_depth  = t.valley_depth;
    if(s.catchment_km2 == null) s.catchment_km2 = t.catchment_km2;
    return s;
  }

  return { atPoint: atPoint, forStation: forStation, decorate: decorate,
           rebuild: function(){ index = null; } };
})();
window.terrainForStation = function(s){ return AGN.terrain.forStation(s); };

AGN.sector = (function(){
  var current='agriculture', listeners=[];
  function labels(){ return (typeof AI_SECTOR_LABELS!=='undefined')?AI_SECTOR_LABELS:{}; }
  function valid(k){
    return (typeof AI_SECTOR_HAZARDS!=='undefined') && !!AI_SECTOR_HAZARDS[k];
  }
  function get(){ return current; }
  function label(k){ return labels()[k||current]||(k||current); }
  function hazards(k){
    try{ return AI_SECTOR_HAZARDS[k||current]||[]; }catch(_){ return []; }
  }
  function set(k, origin){
    if(!valid(k)) return current;

    if(k===current && origin!=='init') return current;
    current=k;
    
    try{
      if(typeof aiState!=='undefined'){
        aiState.sector=k;
        if(typeof aiBuildHazardButtons==='function') aiBuildHazardButtons();
        if(window.AGN&&AGN.services&&AGN.services.has('airisk')) AGN.services.call('airisk','refresh');
      }
    }catch(_){}
    
    
    try{
      var a=document.getElementById('asmtAsset');
      if(a && origin!=='assessments' && a.value!==k){
        var has=Array.prototype.some.call(a.options,function(o){return o.value===k;});
        if(has){
          a.value=k;
          if(window.AGN&&AGN.services&&AGN.services.has('assessments')) AGN.services.call('assessments','run');
          else { try{ a.dispatchEvent(new Event('change',{bubbles:true})); }catch(_){} }
        }
      }
    }catch(_){}
    
    try{ if(window.AGN&&AGN.services&&AGN.services.has('overview')) AGN.services.call('overview','refresh'); }catch(_){}
    
    try{
      var sel=document.getElementById('aiSectorSel');
      if(sel && sel.value!==k) sel.value=k;
      document.querySelectorAll('[data-agn-sector-badge]').forEach(function(el){
        el.textContent=label(k);
      });
    }catch(_){}
    
    try{
      var meta=document.getElementById('aiSectorMeta');
      var M=(typeof AI_SECTOR_METRICS!=='undefined')&&AI_SECTOR_METRICS[k];
      if(meta&&M){
         
        var _T=(typeof aiSectorThresholdText==='function')?aiSectorThresholdText(M)
               :{physical:[],screening:[],physicalNote:'',screeningNote:''};
        var _esc=function(t){ return String(t==null?'':t)
          .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
        meta.innerHTML='<b>'+_esc(label(k))+'</b> · exposed unit: '+_esc(M.unit)
          +'<br><span style="opacity:.8">Loss pathway: '+_esc(M.pathway)+'</span>'
          +'<br><b style="display:block;margin-top:6px">Physical thresholds</b>'
          +'<span style="opacity:.8">'+(_T.physical.length?_esc(_T.physical.join(' · '))
                                       :'none declared for this sector')+'</span>'
          +'<br><span style="opacity:.65;font-size:.9em">'+_esc(_T.physicalNote)+'</span>'
          +(_T.screening.length
             ? ('<br><b style="display:block;margin-top:6px">Screening guidance · NIGRAAN 0-100 index</b>'
               +'<span style="opacity:.8">'+_esc(_T.screening.join(' · '))+'</span>'
               +'<br><span style="opacity:.65;font-size:.9em">'+_esc(_T.screeningNote)+'</span>')
             : '')
          +'<br><span style="opacity:.65;margin-top:6px;display:block">Typical owner: '+_esc(M.owner)+'</span>';
      }
    }catch(_){}
    listeners.forEach(function(fn){ try{ fn(k,origin); }catch(_){} });
    try{ document.dispatchEvent(new CustomEvent('agn:sector',{detail:{sector:k,origin:origin||null}})); }catch(_){}
    return current;
  }
  function on(fn){ if(typeof fn==='function') listeners.push(fn); }
  return { get:get, set:set, on:on, label:label, hazards:hazards, valid:valid,
           list:function(){ return Object.keys(labels()); } };
})();

AGN.renderTerrainPanel = function(lat, lon){
  var t = AGN.terrain.atPoint(Number(lat), Number(lon));
  if(!t || t.slope_deg==null) return '';
  var chip=function(label,value,tone){
    var bg = tone==='warn' ? 'rgba(218,117,15,.10)' : tone==='cool' ? 'rgba(74,140,147,.12)' : 'rgba(12,56,81,.06)';
    var fg = tone==='warn' ? '#8a4a06' : tone==='cool' ? '#2c5f65' : 'var(--navy)';
    return '<span style="display:inline-flex;flex-direction:column;gap:1px;background:'+bg
      +';border-radius:9px;padding:5px 9px;min-width:62px">'
      +'<span style="font-size:0.75rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;opacity:.62;color:'+fg+'">'+label+'</span>'
      +'<span style="font-size:0.75rem;font-weight:800;color:'+fg+'">'+value+'</span></span>';
  };
  var lf={valley_floor:'Valley floor',lower_slope:'Lower slope',flat:'Flat',
          mid_slope:'Mid slope',upper_slope:'Upper slope',ridge:'Ridge'}[t.landform]||t.landform||'—';
  var pool='Low', poolTone='';
  if(t.tpi_300!=null){
    if(t.tpi_300<=-15){ pool='High'; poolTone='cool'; }
    else if(t.tpi_300<=-5){ pool='Moderate'; poolTone='cool'; }
    else if(t.tpi_300>=15){ pool='None (exposed)'; poolTone='warn'; }
  }
  var sky='—', skyTone='';
  if(t.svf!=null){ sky=(t.svf>=0.95)?'Open':(t.svf>=0.85)?'Semi-open':'Enclosed'; if(t.svf<0.85) skyTone='cool'; }
  var far = t.matchKm>1.5 ? '<span style="font-size:0.75rem;opacity:.42;color:var(--navy)">nearest terrain sample '+t.matchKm+' km away</span>' : '';
  return '<div id="machTerrainPanel" style="margin-top:9px;padding-top:9px;border-top:1px solid rgba(12,56,81,.10)">'
    +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap">'
    +'<span style="font-size:0.75rem;font-weight:800;letter-spacing:.07em;text-transform:uppercase;color:var(--navy);opacity:.55">Terrain context</span>'
    +'<span style="font-size:0.75rem;opacity:.42;color:var(--navy)">GLO-30 · 30 m</span>'+far+'</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:6px">'
    +chip('Setting',lf)
    +chip('Faces',(t.facing||'—')+(t.slope_deg!=null?' · '+t.slope_deg+'°':''))
    +chip('Cold pooling',pool,poolTone)
    +chip('Sky',sky,skyTone)
    +'</div></div>';
};


